using System.Globalization;
using PgProj.Engine;

namespace PgProj.Cli;

/// <summary>
/// Decides, writes, and reports where generated files go when files are already there (G-158, G-159): the rule <c>--erd-existing</c> and <c>document --existing</c> share. The files a command writes
/// together are treated as one set: if any of them exists the choice covers all of them, with one time stamp.
/// </summary>
internal static class FilePlacement
{
    /// <summary>Every file pgproj generates carries a line that starts like this near its top, which is how a later run tells such a file from one a person wrote.</summary>
    internal const string MarkerPrefix = "Generated by pgproj ";

    /// <summary>The words a command's messages use.</summary>
    /// <param name="Generator">What the command is called (<c>--erd</c>, <c>document</c>).</param>
    /// <param name="Option">The option that chooses the mode (<c>--erd-existing</c>, <c>--existing</c>).</param>
    /// <param name="Noun">What a file is called (<c>ERD file</c>, <c>documentation file</c>).</param>
    /// <param name="Subject">What was written, as a sentence's subject (<c>The diagram</c>, <c>The documentation</c>).</param>
    internal sealed record Wording(string Generator, string Option, string Noun, string Subject);

    /// <summary>What <see cref="Decide"/> decided.</summary>
    /// <param name="Paths">Where to write each file asked for, in the order they were given: the same paths, or time-stamped ones when the existing files are kept.</param>
    /// <param name="Moves">The existing files to rename first (a backup).</param>
    /// <param name="Placement">What was done and why, for a report.</param>
    internal sealed record Decision(IReadOnlyList<string> Paths, IReadOnlyList<(string From, string To)> Moves, ErdPlacement Placement);

    /// <summary>Whether <paramref name="path"/> is a file pgproj generated: it carries <see cref="MarkerPrefix"/> within its first few lines.</summary>
    internal static bool IsGenerated(string path)
        => File.ReadLines(path).Take(5).Any(static line => line.Contains(MarkerPrefix, StringComparison.Ordinal));

    /// <summary>
    /// Decides what <paramref name="existing"/> means for the files that already exist among <paramref name="paths"/>, without touching them. Left to the default, generated files are backed up and
    /// any file a person wrote is kept, which is noticed (even with <c>--quiet</c>) because the files are not where they were asked for.
    /// </summary>
    internal static Decision Decide(IReadOnlyList<string> paths, ErdExisting existing, DateTime generatedUtc, CliLog log, Wording wording)
    {
        var (generator, option, _, subject) = wording;
        var present = paths.Where(File.Exists).ToArray();
        if (present.Length == 0)
        {
            return new Decision(paths, [], new ErdPlacement("Written", "No file was there."));
        }

        var mode = existing;
        var reason = $"Specified: {option} {existing.ToString().ToLowerInvariant()}.";
        string? notWritten = null;
        if (mode == ErdExisting.Default)
        {
            var written = present.Where(static path => !IsGenerated(path)).ToArray();
            mode = written.Length == 0 ? ErdExisting.Backup : ErdExisting.Keep;
            reason = written.Length == 0
                ? $"Default (no {option}): the existing file was written by {generator}, so it is backed up."
                : $"Default (no {option}): the existing file was not written by {generator}, so it is kept.";
            if (written.Length > 0)
            {
                notWritten = $"{string.Join(" and ", written)} {(written.Length == 1 ? "was" : "were")} not written by {generator}, so {(written.Length == 1 ? "it is" : "they are")} kept; use {option} overwrite or backup to replace {(written.Length == 1 ? "it" : "them")}.";
            }
        }

        if (mode == ErdExisting.Overwrite)
        {
            return new Decision(paths, [], new ErdPlacement("Overwrote the existing file.", reason));
        }

        var stamp = generatedUtc.ToUniversalTime().ToString("yyyy-MM-dd-HH-mm-ss", CultureInfo.InvariantCulture);
        string Stamped(string path, string suffix)
        {
            var extension = Path.GetExtension(path);
            return $"{path[..^extension.Length]}.{stamp}{suffix}{extension}";
        }

        // Take the first stamp (time, then time-2, time-3, ...) that no file of the set already has, so nothing is replaced silently.
        var taken = mode == ErdExisting.Backup ? present : paths;
        var suffix = string.Empty;
        for (var attempt = 2; taken.Any(path => File.Exists(Stamped(path, suffix))); attempt++)
        {
            suffix = $"-{attempt.ToString(CultureInfo.InvariantCulture)}";
        }

        if (mode == ErdExisting.Keep)
        {
            var kept = paths.Select(path => Stamped(path, suffix)).ToArray();
            if (notWritten is not null)
            {
                log.Notice($"{notWritten} {subject} was written to {string.Join(" and ", kept)} instead.");
            }

            return new Decision(kept, [], new ErdPlacement($"Kept the existing file and wrote {subject.ToLowerInvariant()} under a new name, {Path.GetFileName(kept[0])}.", reason));
        }

        var moves = present.Select(path => (path, Stamped(path, suffix))).ToArray();
        return new Decision(paths, moves, new ErdPlacement($"Backed up the existing file to {string.Join(" and ", moves.Select(static move => Path.GetFileName(move.Item2)))} and wrote {subject.ToLowerInvariant()} at the path.", reason));
    }

    /// <summary>Renames the existing files a decision says to move, and says so.</summary>
    internal static void Apply(Decision decision, CliLog log, string noun)
    {
        foreach (var (from, to) in decision.Moves)
        {
            File.Move(from, to);
            log.Info($"Moved existing {noun} to: {to}");
        }
    }

    /// <summary>
    /// Writes <paramref name="files"/> (the final path of each, and its text) so a failure never leaves a new file beside an old one or a half-written file at a path: each is written to a temporary name,
    /// then the renames the decision calls for are made, then the temporary files are moved into place.
    /// </summary>
    internal static async Task CommitAsync(IReadOnlyList<(string Path, string Text)> files, Decision decision, CliLog log, string noun, CancellationToken cancellationToken)
    {
        var staged = new List<(string Temporary, string Final)>();
        try
        {
            foreach (var (path, text) in files)
            {
                Directory.CreateDirectory(Path.GetDirectoryName(path) ?? Environment.CurrentDirectory);
                var temporary = Path.Combine(Path.GetDirectoryName(path) ?? Environment.CurrentDirectory, $".{Path.GetFileName(path)}.{Guid.NewGuid():N}.tmp");
                await File.WriteAllTextAsync(temporary, text, cancellationToken);
                staged.Add((temporary, path));
            }

            Apply(decision, log, noun);
            foreach (var (temporary, final) in staged)
            {
                File.Move(temporary, final, overwrite: true);
            }

            staged.Clear();
        }
        finally
        {
            foreach (var (temporary, _) in staged)
            {
                File.Delete(temporary);
            }
        }
    }
}
